var sze = 50;
var steps;
var numW, numH;
var blocks, pal;

function setup() {
	numW = floor(innerWidth / sze)
	numH = floor(innerHeight / sze)
	createCanvas(numW * sze, numH * sze);
	pixelDensity(1);
	frameRate(10);
	describe("colored pixel blocks moving top right bottom left");

	steps = numW; // floor(random(2, 7));
	blocks = [];

	noStroke();
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function addBlocks() {
	const palettes = [
		["white", "#ff577d","#ff184c"],
		["#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
		["#white", "#8318C7", "#A0183F",]
	]	
	const pal = random(palettes)
	const stps = floor(random(2, 7)); // steps

	// how many tiles
	const numT = floor(random(2, 4 * stps));
	tiles = [];
	for (let i = 0; i < numT; i++) {
		tiles.push(random(pal));
	}

	// how often we insert the tiles
	const numR = floor(random(2 * stps, 4 * stps));
	for (let i = 0; i < numR; i++) {
		blocks = blocks.concat(tiles)
	}
}

function draw() {
	background(32);
	let x = 0, y = 0;

	steps = numW // + floor(random(-1, 1)) // round mathimatically better, but looks to confusing

	const numWH = numW * numH
	const fcs = frameCount * steps;
	// console.log(`Status: len=${blocks.length}, num2=${numWH}, fc*s=${fcs}`);

	// add blocks
	if (blocks.length < numW * numH) {
		addBlocks(blocks)	
		// console.log("blocks added");
	}

	// display blocks
	const startIdx = min([fcs, numWH, blocks.length]); // frameCount * steps + steps - 1,
	// for (let i = 0; i < blocks.length; i++) {
	for (let i = startIdx - 1; i >= 0; i--) {
		fill(blocks[i]);
		rect(x, y, sze, sze);
		x += sze;
		if (x >= width)  {
			// new line
			x = 0;
			y += sze
		}
	}

	// delete x blocks
	if (fcs > numW * numH + steps + 1) { // why ever this formula works ;)
		blocks.splice(0, steps);
		// console.log("blocks deleted");
	}

	// // noLoop() removed for animation
}

function windowResized() {
	setup();
}
